INSERT INTO `notifications` VALUES (1,2,4,'PAYMENT_SUCCESS','Γëí╞Æ├åΓöé Pembayaran Berhasil ╬ô├ç├╢ #ORD-0004','Pembayaran sebesar <strong>Rp 250.000</strong> melalui <strong>Transfer M-Banking (BCA)</strong> untuk pesanan #ORD-0004 telah berhasil kami terima. Terima kasih telah menggunakan HomeCare Service!',0,'2026-10-17 02:28:00'),(2,2,5,'ON_THE_WAY','Γëí╞Æ├£├╣ Teknisi Sedang Menuju Lokasi Anda','Teknisi <strong>Herman</strong> sedang dalam perjalanan menuju rumah Anda untuk pesanan <strong>#ORD-0005</strong>. Pastikan Anda berada di rumah dan siap menerima kedatangan teknisi.',0,'2026-10-21 06:44:11'),(3,2,5,'IN_PROGRESS','Γëí╞Æ├╢┬║ Servis Sedang Dikerjakan','Teknisi <strong>Herman</strong> telah tiba dan mulai mengerjakan servis <strong>AC (Air Conditioner)</strong> (Pesanan <strong>#ORD-0005</strong>). Mohon tunggu sebentar hingga pekerjaan selesai.',0,'2026-10-21 06:44:15'),(4,2,5,'COMPLETED','Γëí╞Æ├ä├½ Servis Selesai ╬ô├ç├╢ #ORD-0005','Pesanan servis #ORD-0005 untuk <strong>AC (Air Conditioner)</strong> telah selesai dikerjakan oleh teknisi <strong>Herman</strong>.<br><strong>Hasil Pemeriksaan:</strong> AC Daikin menyala normal tetapi udara yang keluar tidak dingin dan terjadi kebocoran/tetesan air pada unit indoor. Setelah diperiksa, ditemukan penumpukan kotoran/debu tebal pada evaporator serta saluran pembuangan air (drainase) tersumbat. Tekanan freon juga telah diperiksa dan disesuaikan.<br><strong>Tindakan Perbaikan:</strong> Pembersihan total unit indoor &amp; outdoor (cuci AC/cuci besar).   Pembersihan dan pelancaran saluran pembuangan air (drainase) yang tersumbat.<br><strong>Catatan Teknisi:</strong> Disarankan untuk melakukan cuci/servis berkala setiap 3╬ô├ç├┤4 bulan sekali agar kinerja pendinginan tetap optimal dan mencegah kebocoran air berulang. Garansi servis pengerjaan berlaku selama 30 hari.<br><strong>Γëí╞Æ├åΓûæ Total Tagihan: Rp 300.000</strong>',0,'2026-10-21 06:46:11'),(5,2,6,'ACCEPTED','╬ô┬ú├á Teknisi Menerima Pesanan Anda','Teknisi <strong>Herman</strong> telah menerima pesanan servis <strong>#ORD-0006</strong> untuk peralatan <strong>Televisi (TV)</strong>. Teknisi akan segera menghubungi Anda dan berangkat ke lokasi.',0,'2026-10-23 04:05:00'),(6,2,6,'ON_THE_WAY','Γëí╞Æ├£├╣ Teknisi Sedang Menuju Lokasi Anda','Teknisi <strong>Herman</strong> sedang dalam perjalanan menuju rumah Anda untuk pesanan <strong>#ORD-0006</strong>. Pastikan Anda berada di rumah dan siap menerima kedatangan teknisi.',0,'2026-10-23 04:05:26'),(7,2,6,'IN_PROGRESS','Γëí╞Æ├╢┬║ Servis Sedang Dikerjakan','Teknisi <strong>Herman</strong> telah tiba dan mulai mengerjakan servis <strong>Televisi (TV)</strong> (Pesanan <strong>#ORD-0006</strong>). Mohon tunggu sebentar hingga pekerjaan selesai.',0,'2026-10-23 04:05:35'),(8,2,5,'PAYMENT_SUCCESS','Γëí╞Æ├åΓöé Pembayaran Berhasil ╬ô├ç├╢ #ORD-0005','Pembayaran sebesar <strong>Rp 300.000</strong> melalui <strong>Tunai (Cash)</strong> untuk pesanan #ORD-0005 telah berhasil kami terima. Terima kasih telah menggunakan HomeCare Service!',0,'2026-10-25 02:34:54'),(9,2,7,'ACCEPTED','╬ô┬ú├á Teknisi Menerima Pesanan Anda','Teknisi <strong>Herman</strong> telah menerima pesanan servis <strong>#ORD-0007</strong> untuk peralatan <strong>Kulkas / Lemari Es</strong>. Teknisi akan segera menghubungi Anda dan berangkat ke lokasi.',0,'2026-10-25 14:06:53'),(10,2,7,'ON_THE_WAY','Γëí╞Æ├£├╣ Teknisi Sedang Menuju Lokasi Anda','Teknisi <strong>Herman</strong> sedang dalam perjalanan menuju rumah Anda untuk pesanan <strong>#ORD-0007</strong>. Pastikan Anda berada di rumah dan siap menerima kedatangan teknisi.',0,'2026-10-25 14:07:02'),(11,2,7,'IN_PROGRESS','Γëí╞Æ├╢┬║ Servis Sedang Dikerjakan','Teknisi <strong>Herman</strong> telah tiba dan mulai mengerjakan servis <strong>Kulkas / Lemari Es</strong> (Pesanan <strong>#ORD-0007</strong>). Mohon tunggu sebentar hingga pekerjaan selesai.',0,'2026-10-25 14:07:07'),(12,2,6,'COMPLETED','Γëí╞Æ├ä├½ Servis Selesai ╬ô├ç├╢ #ORD-0006','Pesanan servis #ORD-0006 untuk <strong>Televisi (TV)</strong> telah selesai dikerjakan oleh teknisi <strong>Herman</strong>.<br><strong>Hasil Pemeriksaan:</strong> Terdapat kerusakan pada panel layar TV Samsung, di mana muncul garis-garis vertikal/horizontal pada layar serta sebagian area layar tampak berbayang. Kendala ini berasal dari gangguan pada modul panel atau jalur fleksibel layar.<br><strong>Tindakan Perbaikan:</strong> Melakukan pembongkaran unit, pemeriksaan jalur fleksibel panel (COF), pembersihan konektor, serta penggantian modul layar/kabel flex untuk menghilangkan garis dan bayangan pada tampilan visual.<br><strong>Catatan Teknisi:</strong> Disarankan untuk menjaga kelembapan ruangan agar komponen panel tetap awet dan terhindar dari korosi. Garansi servis perbaikan ini berlaku selama 1 bulan ke depan untuk kendala yang sama.<br><strong>Γëí╞Æ├åΓûæ Total Tagihan: Rp 500.000</strong>',0,'2026-10-27 12:48:08'),(13,2,11,'ACCEPTED','╬ô┬ú├á Teknisi Menerima Pesanan Anda','Teknisi <strong>Herman</strong> telah menerima pesanan servis <strong>#ORD-0011</strong> untuk peralatan <strong>Magic Jar</strong>. Teknisi akan segera menghubungi Anda dan berangkat ke lokasi.',0,'2026-10-27 12:55:12'),(14,2,11,'ON_THE_WAY','Γëí╞Æ├£├╣ Teknisi Sedang Menuju Lokasi Anda','Teknisi <strong>Herman</strong> sedang dalam perjalanan menuju rumah Anda untuk pesanan <strong>#ORD-0011</strong>. Pastikan Anda berada di rumah dan siap menerima kedatangan teknisi.',0,'2026-10-27 12:55:16'),(15,2,11,'IN_PROGRESS','Γëí╞Æ├╢┬║ Servis Sedang Dikerjakan','Teknisi <strong>Herman</strong> telah tiba dan mulai mengerjakan servis <strong>Magic Jar</strong> (Pesanan <strong>#ORD-0011</strong>). Mohon tunggu sebentar hingga pekerjaan selesai.',0,'2026-10-27 13:10:15'),(16,2,11,'COMPLETED','Γëí╞Æ├ä├½ Servis Selesai ╬ô├ç├╢ #ORD-0011','Pesanan servis #ORD-0011 untuk <strong>Magic Jar</strong> telah selesai dikerjakan oleh teknisi <strong>Herman</strong>.<br><strong>Hasil Pemeriksaan:</strong> Berdasarkan keluhan unit mati total, hasil pemeriksaan menunjukkan bahwa thermal fuse (sekring suhu) pada bagian dalam unit terputus akibat overheat atau tegangan tidak stabil. Hal ini menyebabkan aliran listrik utama terputus sepenuhnya ke elemen pemanas.<br><strong>Tindakan Perbaikan:</strong> Dilakukan pembongkaran bodi bawah, penggantian suku cadang thermal fuse (sekring suhu) baru dengan spesifikasi yang sesuai standar pabrik, serta pengecekan kelayakan kabel power dan pembersihan area elemen pemanas.<br><strong>Catatan Teknisi:</strong> Unit sudah dites dan berfungsi normal. Selalu pastikan bagian luar panci (inner pot) dilap hingga benar-benar kering sebelum dimasukkan ke dalam magic jar untuk mencegah korsleting. Garansi perbaikan berlaku selama 30 hari untuk kerusakan pada komponen yang sama.<br><strong>Γëí╞Æ├åΓûæ Total Tagihan: Rp 100.000</strong>',0,'2026-10-27 13:11:40'),(17,2,12,'ACCEPTED','╬ô┬ú├á Teknisi Menerima Pesanan Anda','Teknisi <strong>Herman</strong> telah menerima pesanan servis <strong>#ORD-0012</strong> untuk peralatan <strong>Kompor Gas / Listrik</strong>. Teknisi akan segera menghubungi Anda dan berangkat ke lokasi.',0,'2026-10-30 01:31:41'),(18,2,12,'ON_THE_WAY','Γëí╞Æ├£├╣ Teknisi Sedang Menuju Lokasi Anda','Teknisi <strong>Herman</strong> sedang dalam perjalanan menuju rumah Anda untuk pesanan <strong>#ORD-0012</strong>. Pastikan Anda berada di rumah dan siap menerima kedatangan teknisi.',0,'2026-10-30 01:31:59'),(19,2,12,'IN_PROGRESS','Γëí╞Æ├╢┬║ Servis Sedang Dikerjakan','Teknisi <strong>Herman</strong> telah tiba dan mulai mengerjakan servis <strong>Kompor Gas / Listrik</strong> (Pesanan <strong>#ORD-0012</strong>). Mohon tunggu sebentar hingga pekerjaan selesai.',0,'2026-10-30 01:39:09');
