INSERT INTO `service_orders` VALUES (1,1,1,1,'AC bocor air di indoor dan kurang dingin','Analisis AI menunjukkan pipa drainase tersumbat debu/lumut dan filter kotor.','COMPLETED','2026-10-07 08:06:33',NULL,'Jl. Kemang Raya No. 15, Jakarta Selatan',150000.00,150000.00,NULL,'2026-10-06 01:06:33','2026-10-10 01:06:33'),(2,1,2,5,'Kulkas bagian bawah tidak dingin, tapi freezer atas membeku normal','Analisis AI mengindikasikan gangguan pada sistem defrost otomatis atau kipas sirkulasi chiller.','IN_PROGRESS','2026-10-10 10:06:33',NULL,'Jl. Kemang Raya No. 15, Jakarta Selatan',250000.00,NULL,NULL,'2026-10-09 01:06:33','2026-10-10 01:06:33'),(3,1,7,9,'Mesin cuci mengeluarkan bunyi berdecit keras saat proses spin/pengeringan','Analisis AI menduga tali fanbelt aus atau ada bantalan bearing tabung yang perlu pelumasan.','COMPLETED','2026-10-11 08:06:33',NULL,'Jl. Kemang Raya No. 15, Jakarta Selatan',200000.00,150000.00,NULL,'2026-10-10 01:06:33','2026-10-17 01:43:32'),(4,2,7,22,'Mesin cuci tidak mau berputar saat mode pengering','=== HASIL DIAGNOSIS AWAL AI ===\r\nTingkat Prioritas: TINGGI\r\n\r\nPenjelasan & Analisis Kerusakan:\r\nMesin cuci yang tidak berputar atau sistem pengeringnya macet menandakan terganggunya transfer tenaga dari motor penggerak ke tabung cuci atau terpicunya mekanisme sensor keselamatan mesin. Pada sebagian besar mesin cuci otomatis maupun dua tabung, modul elektronik akan menghentikan putaran motor jika mendeteksi pintu tidak terkunci rapat, beban cucian tidak seimbang, atau komponen transmisi kehilangan daya cengkeram.\r\n\r\nKemungkinan Penyebab Teknis:\r\nFaktor penyebab yang dominan meliputi tali karet transmisi (fanbelt) yang sudah aus, kendur, atau putus; kapasitor motor starter yang kehilangan kapasitas microfarad; saklar sensor switch pintu (door lock safety) yang kotor atau patah; serta kemungkinan beban pakaian yang dimasukkan melebihi batas kapasitas maksimal mesin.\r\n\r\nPanduan & Rekomendasi Tindakan Awal:\r\nKurangi jumlah pakaian di dalam tabung untuk meringankan beban kerja motor dan ratakan susunan cucian agar seimbang. Pastikan penutup atau pintu mesin cuci tertutup rapat sempurna hingga terdengar bunyi klik pengaman. Selalu cabut kabel daya dari stop kontak sebelum memeriksa bagian dalam tabung mesin.\r\n\r\nSaran Pemeriksaan Teknisi:\r\nDisarankan memanggil teknisi untuk melakukan penggantian tali fanbelt, pemeriksaan kapasitor motor dengan alat kapasitansi meter, atau perbaikan switch sensor pengunci pintu.\r\n\r\nCatatan / Disclaimer:\r\nHasil ini merupakan diagnosis awal dari AI dan bukan diagnosis teknisi pasti. Pemeriksaan fisik secara langsung oleh teknisi tetap diperlukan.','COMPLETED','2026-10-18 09:00:00',NULL,'Jln. Perjuangan No. 10',NULL,250000.00,NULL,'2026-10-17 01:16:01','2026-10-17 01:48:48'),(5,2,7,23,'AC menyala tapi tidak dingin dan bocor air','=== HASIL DIAGNOSIS AWAL AI ===\r\nTingkat Prioritas: SEDANG\r\n\r\nPenjelasan & Analisis Kerusakan:\r\nBerdasarkan gejala yang dialami, AC yang menyala namun kurang dingin serta disertai tetesan air menunjukkan adanya hambatan signifikan pada sirkulasi udara dan sistem drainase unit indoor. Ketika saringan filter udara atau kisi-kisi evaporator tertutup debu pekat, penyerapan panas ruangan tidak berlangsung optimal sehingga permukaan evaporator mengalami pendinginan berlebih (frosting) yang kemudian mencair dan meluap dari bak talang air karena saluran pipa pembuangan tersumbat lumut atau kotoran.\r\n\r\nKemungkinan Penyebab Teknis:\r\nPenyebab utama dari kendala ini adalah akumulasi kotoran dan debu pekat pada filter udara serta koil pendingin indoor, penyumbatan lendir lumut pada pipa pembuangan air kondensasi, serta potensi penurunan tekanan gas refrigerant (freon) akibat kebocoran mikro pada sambungan pipa tembaga atau nepel. Selain itu, sirip kondensor pada unit outdoor yang kotor juga dapat menghambat pelepasan panas sehingga kompresor cepat panas dan memutus siklus pendinginan secara prematur.\r\n\r\nPanduan & Rekomendasi Tindakan Awal:\r\nSebagai langkah penanganan awal yang aman, segera matikan unit AC dan bersihkan saringan filter udara pada panel indoor menggunakan air mengalir lalu keringkan sebelum dipasang kembali. Pastikan jalur selang pembuangan di luar ruangan berada dalam posisi menurun bebas dan tidak tertekuk ataupun terendam air. Hindari membongkar penutup modul kelistrikan indoor atau mengisi freon secara mandiri demi keamanan dan keselamatan perangkat.\r\n\r\nSaran Pemeriksaan Teknisi:\r\nSangat disarankan untuk menjadwalkan servis cuci AC berkala (steam cleaning) secara menyeluruh serta pengecekan tekanan freon dan arus kompresor oleh teknisi profesional guna memastikan kinerja pendinginan kembali optimal.\r\n\r\nCatatan / Disclaimer:\r\nHasil ini merupakan diagnosis awal dari AI dan bukan diagnosis teknisi pasti. Pemeriksaan fisik secara langsung oleh teknisi tetap diperlukan.','COMPLETED','2026-10-18 09:00:00',NULL,'Jln. Perjuangan No. 10',NULL,300000.00,NULL,'2026-10-17 01:56:29','2026-10-21 06:46:11'),(6,2,7,24,'Muncul garis-garis vertikal/horizontal di layar, atau sebagian layar berbayang/pecah dari dalam','=== HASIL DIAGNOSIS AWAL AI ===\r\nTingkat Prioritas: SEDANG\r\n\r\nPenjelasan & Analisis Kerusakan:\r\nKerusakan pada televisi seperti layar gelap namun suara tetap terdengar, layar bergaris, atau TV tidak menyala biasanya bersumber dari degradasi rangkaian pencahayaan latar (backlight panel) atau gangguan pada modul regulator pencatu daya (power supply board). Rangkaian proteksi TV modern akan secara otomatis mematikan layar jika mendeteksi adanya ketidakstabilan voltase pada deretan lampu LED backlight.\r\n\r\nKemungkinan Penyebab Teknis:\r\nPenyebab paling umum adalah lampu strip LED backlight panel yang sudah putus atau melemah akibat usia pakai, komponen elco/kapasitor pada power board yang mengalami penurunan kapasitas tegangan, atau kabel pita konektor LVDS antara mainboard dan panel T-Con yang longgar atau berdebu.\r\n\r\nPanduan & Rekomendasi Tindakan Awal:\r\nPastikan TV terhubung pada colokan listrik yang stabil dan periksa kembali sambungan kabel HDMI, Set Top Box, atau antena. Hindari mengetuk, menekan, atau menyemprotkan cairan pembersih secara langsung ke permukaan panel kaca layar TV.\r\n\r\nSaran Pemeriksaan Teknisi:\r\nPerbaikan TV memerlukan teknisi spesialis untuk melakukan pembongkaran panel secara presisi di lingkungan bebas debu serta pengujian modul menggunakan voltmeter dan backlight tester.\r\n\r\nCatatan / Disclaimer:\r\nHasil ini merupakan diagnosis awal dari AI dan bukan diagnosis teknisi pasti. Pemeriksaan fisik secara langsung oleh teknisi tetap diperlukan.','COMPLETED','2026-10-24 09:00:00',NULL,'Jln. Perjuangan No. 10',NULL,500000.00,NULL,'2026-10-23 04:02:56','2026-10-27 12:48:08'),(7,2,7,25,'Bagian bawah kulkas tidak dingin tetapi freezer beku','=== HASIL DIAGNOSIS AWAL AI ===\r\nTingkat Prioritas: TINGGI\r\n\r\nPenjelasan & Analisis Kerusakan:\r\nKulkas yang mengalami penurunan suhu dingin atau tidak mampu membekukan es secara optimal menunjukkan adanya disrupsi pada siklus termodinamika pendinginan atau kebocoran isolasi termal kabinet. Kulkas bekerja dengan menyerap panas dari dalam kabinet dan membuangnya melalui kondensor di bagian belakang atau samping bodi; jika proses ini terhambat, suhu dalam kabinet akan terus meningkat dan membebani kompresor.\r\n\r\nKemungkinan Penyebab Teknis:\r\nPenyebab yang sering terjadi antara lain karet gasket pintu yang mengeras, robek, atau kotor sehingga udara hangat dari luar terus masuk; penumpukan debu tebal pada koil kondensor dan motor fan pendingin; gangguan pada sistem defrost otomatis (seperti timer defrost, bimetal defrost, atau elemen heater pemanas); serta kemungkinan sirkulasi gas freon yang berkurang akibat kebocoran mikro.\r\n\r\nPanduan & Rekomendasi Tindakan Awal:\r\nBersihkan karet lis pintu kulkas dengan kain basah hangat dan pastikan pintu menutup rapat tanpa ada celah udara. Berikan jarak ventilasi minimal 10 sampai 15 cm antara bagian belakang serta samping kulkas dengan dinding ruangan. Hindari memasukkan makanan atau cairan yang masih bersuhu panas ke dalam kulkas.\r\n\r\nSaran Pemeriksaan Teknisi:\r\nPenanganan teknisi sangat dianjurkan untuk memeriksa sistem kelistrikan defrost bimetal, relay start kompresor, serta pengecekan sirkulasi freon demi mencegah kerusakan kompresor yang lebih berat.\r\n\r\nCatatan / Disclaimer:\r\nHasil ini merupakan diagnosis awal dari AI dan bukan diagnosis teknisi pasti. Pemeriksaan fisik secara langsung oleh teknisi tetap diperlukan.','IN_PROGRESS','2026-10-26 16:20:00',NULL,'Jln. Perjuangan No. 10',NULL,NULL,NULL,'2026-10-23 14:20:42','2026-10-25 14:07:07'),(11,2,7,26,'Magic jar mati total dan tidak bisa digunakan untuk memasak maupun menghangatkan sama sekali.','=== HASIL DIAGNOSIS AWAL AI ===\r\nTingkat Prioritas: SEDANG\r\n\r\nPenjelasan & Analisis Kerusakan:\r\nKendala operasional pada peralatan rumah tangga umumnya dipengaruhi oleh penurunan kinerja elemen pemanas atau motor penggerak, keausan kabel transmisi daya, atau akumulasi kotoran sisa pemakaian pada bagian mekanis. Kondisi operasional yang dipaksakan saat komponen internal mengalami degradasi dapat memicu panas berlebih dan berisiko merusak modul proteksi alat.\r\n\r\nKemungkinan Penyebab Teknis:\r\nFaktor penyebab mencakup penurunan ketahanan isolasi komponen kelistrikan internal, koneksi kabel atau kontak saklar daya yang longgar dan berkarat, serta timbunan kerak, debu, atau sisa residu yang menghambat pergerakan mekanis perangkat.\r\n\r\nPanduan & Rekomendasi Tindakan Awal:\r\nSegera matikan alat dan cabut steker dari colokan listrik setelah digunakan atau saat terdeteksi kelainan fungsi. Bersihkan permukaan luar perangkat secara rutin dan jangan membongkar casing internal sendiri jika tidak memiliki peralatan uji kelistrikan yang memadai.\r\n\r\nSaran Pemeriksaan Teknisi:\r\nPemeriksaan langsung oleh teknisi profesional sangat disarankan guna menguji kelayakan komponen, memastikan keamanan isolasi listrik, dan melakukan penggantian suku cadang yang presisi.\r\n\r\nCatatan / Disclaimer:\r\nHasil ini merupakan diagnosis awal dari AI dan bukan diagnosis teknisi pasti. Pemeriksaan fisik secara langsung oleh teknisi tetap diperlukan.','COMPLETED','2026-10-29 11:55:00',NULL,'Jln. Perjuangan No. 10',NULL,100000.00,NULL,'2026-10-27 12:54:24','2026-10-27 13:11:40'),(12,2,7,27,'Nyala api kompornya jadi warna merah dan kuning, bukan biru. Jadinya bagian bawah wajan dan panci saya pada hitam gosong semua setiap habis dipakai masak.','=== HASIL DIAGNOSIS AWAL AI ===\r\nTingkat Prioritas: SEDANG\r\n\r\nPenjelasan & Analisis Kerusakan:\r\nKendala operasional pada peralatan rumah tangga umumnya dipengaruhi oleh penurunan kinerja elemen pemanas atau motor penggerak, keausan kabel transmisi daya, atau akumulasi kotoran sisa pemakaian pada bagian mekanis. Kondisi operasional yang dipaksakan saat komponen internal mengalami degradasi dapat memicu panas berlebih dan berisiko merusak modul proteksi alat.\r\n\r\nKemungkinan Penyebab Teknis:\r\nFaktor penyebab mencakup penurunan ketahanan isolasi komponen kelistrikan internal, koneksi kabel atau kontak saklar daya yang longgar dan berkarat, serta timbunan kerak, debu, atau sisa residu yang menghambat pergerakan mekanis perangkat.\r\n\r\nPanduan & Rekomendasi Tindakan Awal:\r\nSegera matikan alat dan cabut steker dari colokan listrik setelah digunakan atau saat terdeteksi kelainan fungsi. Bersihkan permukaan luar perangkat secara rutin dan jangan membongkar casing internal sendiri jika tidak memiliki peralatan uji kelistrikan yang memadai.\r\n\r\nSaran Pemeriksaan Teknisi:\r\nPemeriksaan langsung oleh teknisi profesional sangat disarankan guna menguji kelayakan komponen, memastikan keamanan isolasi listrik, dan melakukan penggantian suku cadang yang presisi.\r\n\r\nCatatan / Disclaimer:\r\nHasil ini merupakan diagnosis awal dari AI dan bukan diagnosis teknisi pasti. Pemeriksaan fisik secara langsung oleh teknisi tetap diperlukan.','IN_PROGRESS','2026-10-31 09:00:00',NULL,'Jln. Perjuangan No. 10',NULL,NULL,NULL,'2026-10-30 01:29:34','2026-10-30 01:39:09');
