INSERT INTO `service_reports` VALUES (1,1,1,'Filter indoor penuh debu tebal dan saluran pipa drainase tersumbat lendir lumut. Freon masih normal (80 PSI).','Pembersihan filter udara, steam cuci koil indoor dan outdoor, serta flushing saluran pembuangan air.','AC sudah berfungsi dingin maksimal dan tidak ada tetesan air lagi. Disarankan servis berkala 3 bulan sekali.',150000.00,'2026-10-07 08:06:33','2026-10-10 01:06:33'),(2,3,7,'Mesin cuci mengeluarkan bunyi berdecit keras saat proses pengeringan. Setelah diperiksa, suara tersebut disebabkan oleh keausan pada belt (sabuk penggerak) atau kurangnya pelumasan pada komponen poros/bearing tabung pengering.','Melakukan penyetelan ulang serta pelumasan pada komponen penggerak. Penggantian suku cadang belt penggerak baru.','Disarankan agar tidak mencuci melebihi kapasitas muatan mesin dan rutin membersihkan bagian tabung agar komponen tetap awet. Garansi servis berlaku selama 1 minggu untuk perbaikan yang sama.',150000.00,'2026-10-17 03:43:32','2026-10-17 01:43:32'),(3,4,7,'Mesin cuci tidak mau berputar sama sekali saat masuk ke mode pengering. Setelah diperiksa, kendala disebabkan oleh kapasitor pengering yang lemah/rusak, belt (sabuk penggerak) yang putus atau kendur, atau switch pintu pengering yang tidak berfungsi.','Melakukan pemeriksaan kelistrikan dan mekanik, penyetelan ulang komponen penggerak, serta penggantian suku cadang','Hindari membebaninya melebihi kapasitas maksimal saat mengeringkan pakaian agar komponen dinamo dan kapasitor lebih awet. Garansi servis berlaku 1 minggu untuk perbaikan komponen terkait.',250000.00,'2026-10-17 03:48:48','2026-10-17 01:48:48'),(4,5,7,'AC Daikin menyala normal tetapi udara yang keluar tidak dingin dan terjadi kebocoran/tetesan air pada unit indoor. Setelah diperiksa, ditemukan penumpukan kotoran/debu tebal pada evaporator serta saluran pembuangan air (drainase) tersumbat. Tekanan freon juga telah diperiksa dan disesuaikan.','Pembersihan total unit indoor & outdoor (cuci AC/cuci besar).   Pembersihan dan pelancaran saluran pembuangan air (drainase) yang tersumbat.','Disarankan untuk melakukan cuci/servis berkala setiap 3╬ô├ç├┤4 bulan sekali agar kinerja pendinginan tetap optimal dan mencegah kebocoran air berulang. Garansi servis pengerjaan berlaku selama 30 hari.',300000.00,'2026-10-21 08:46:11','2026-10-21 06:46:11'),(5,6,7,'Terdapat kerusakan pada panel layar TV Samsung, di mana muncul garis-garis vertikal/horizontal pada layar serta sebagian area layar tampak berbayang. Kendala ini berasal dari gangguan pada modul panel atau jalur fleksibel layar.','Melakukan pembongkaran unit, pemeriksaan jalur fleksibel panel (COF), pembersihan konektor, serta penggantian modul layar/kabel flex untuk menghilangkan garis dan bayangan pada tampilan visual.','Disarankan untuk menjaga kelembapan ruangan agar komponen panel tetap awet dan terhindar dari korosi. Garansi servis perbaikan ini berlaku selama 1 bulan ke depan untuk kendala yang sama.',500000.00,'2026-10-27 13:48:08','2026-10-27 12:48:08'),(6,11,7,'Berdasarkan keluhan unit mati total, hasil pemeriksaan menunjukkan bahwa thermal fuse (sekring suhu) pada bagian dalam unit terputus akibat overheat atau tegangan tidak stabil. Hal ini menyebabkan aliran listrik utama terputus sepenuhnya ke elemen pemanas.','Dilakukan pembongkaran bodi bawah, penggantian suku cadang thermal fuse (sekring suhu) baru dengan spesifikasi yang sesuai standar pabrik, serta pengecekan kelayakan kabel power dan pembersihan area elemen pemanas.','Unit sudah dites dan berfungsi normal. Selalu pastikan bagian luar panci (inner pot) dilap hingga benar-benar kering sebelum dimasukkan ke dalam magic jar untuk mencegah korsleting. Garansi perbaikan berlaku selama 30 hari untuk kerusakan pada komponen yang sama.',100000.00,'2026-10-27 14:11:40','2026-10-27 13:11:40');
/*!40000 ALTER TABLE `service_reports` ENABLE KEYS */;
UNLOCK TABLES;

