INSERT INTO `whatsapp_notifications` VALUES (1,7,'SERVICE_IN_PROGRESS','6285314724809','[pesan telah dikirim]','fonnte','Array','SENT',NULL,1,'2026-10-25 14:07:09','2026-10-25 15:07:09','2026-10-25 14:07:09'),(14,6,'SERVICE_COMPLETED','6285314724809','Halo Qonita Goniyun Ulum,\n\nKabar baik! Perbaikan peralatan Anda telah selesai.\n\nNomor Pesanan: #ORD-0006\nPeralatan: Televisi (TV)\nStatus: Selesai Diperbaiki\n\nTerima kasih telah menggunakan HomeCare Service.','fonnte',NULL,'FAILED','Koneksi ke Fonnte gagal: cURL errno 28: Request timeout',1,'2026-10-27 12:48:23',NULL,'2026-10-27 12:48:23'),(15,11,'SERVICE_ON_THE_WAY','6285314724809','Halo Qonita Goniyun Ulum,\n\nTeknisi HomeCare Service sedang menuju lokasi Anda untuk menangani pesanan servis.\n\nNomor Pesanan: #ORD-0011\nPeralatan: Magic Jar\nStatus: Teknisi Sedang Menuju Lokasi\n\nMohon pastikan Anda dapat dihubungi saat teknisi tiba.\n\nTerima kasih telah menggunakan HomeCare Service.','fonnte','188740160','SENT',NULL,1,'2026-10-27 12:55:17','2026-10-27 13:55:17','2026-10-27 12:55:17'),(16,11,'SERVICE_IN_PROGRESS','6285314724809','Halo Qonita Goniyun Ulum,\n\nKami informasikan bahwa perbaikan peralatan Anda sedang berlangsung.\n\nNomor Pesanan: #ORD-0011\nPeralatan: Magic Jar\nStatus: Sedang Diperbaiki\n\nTerima kasih telah menggunakan HomeCare Service.','fonnte','188742492','SENT',NULL,1,'2026-10-27 13:10:18','2026-10-27 14:10:18','2026-10-27 13:10:18'),(17,11,'SERVICE_COMPLETED','6285314724809','Halo Qonita Goniyun Ulum,\n\nKabar baik! Perbaikan peralatan Anda telah selesai.\n\nNomor Pesanan: #ORD-0011\nPeralatan: Magic Jar\nStatus: Selesai Diperbaiki\n\nTerima kasih telah menggunakan HomeCare Service.','fonnte','188742676','SENT',NULL,1,'2026-10-27 13:11:43','2026-10-27 14:11:43','2026-10-27 13:11:43'),(18,12,'SERVICE_ON_THE_WAY','6283159328220','Halo Qonita Goniyun Ulum,\n\nTeknisi HomeCare Service sedang menuju lokasi Anda untuk menangani pesanan servis.\n\nNomor Pesanan: #ORD-0012\nPeralatan: Kompor Gas